sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    // Add your code here
    if (!current.production_year_from || !current.type_code_number) {
        return;
    }

    var tsn = current.type_code_number.trim();
    var year = new GlideDate();
    year.setValue(current.production_year_from);
    var cutoff = new GlideDate();
    cutoff.setValue('2000-12-31');
    //var isValid = true;
	/* gs.addErrorMessage(tsn);
    gs.addErrorMessage(year);
    gs.addErrorMessage('hi'); */
    if (year <= cutoff) {
        // Fahrzeuge mit Baujahr bis 2000: TSN = 3 Ziffern
        if (!/^\d{3}$/.test(tsn)) {
            gs.addErrorMessage(gs.getMessage("invalid_tsn_format"));
            current.setAbortAction(true);
        }
    } else {
        // Fahrzeuge ab 2001: TSN = 3 Buchstaben
        if (!/^[A-Z]{3}$/i.test(tsn)) {
            gs.addErrorMessage(gs.getMessage("invalid_tsn_format"));
            current.setAbortAction(true);
        }
    }


    /* 	if (year <= '20001231') {
    		// Vor 2001: nur 3 Ziffern erlaubt
    		isValid = /^[0-9]{3}$/.test(tsn);
    	} else {
    		// Ab 2001: nur 3 Buchstaben erlaubt
    		isValid = /^[A-Z]{3}$/i.test(tsn);
    	}
    	if (!isValid) {
    		gs.addErrorMessage(gs.getMessage("invalid_tsn_format"));
    		current.setAbortAction(true);
    	} */



})(current, previous);
